/// <summary>
/// CB616_TMSEngineSOCancellation
/// CB624_TMSEngineSOCreation
/// Class to proceede with the cancellation process for TMS engine
/// </summary>
internal final class METTMSEngineSalesOrderProccess_Cancellation extends METTMSEngineSalesOrderProccess
{

}

Method.Source:
/// <summary>
/// Run the TMS cancellation
/// </summary>
public void run()
{
    if (salesTable.SalesStatus == SalesStatus::Canceled &&
        !salesTable.METIsSalesOrderExcluded() &&
        carrierCode &&
        this.useTMSEngine() &&
        (!isSalesOrderPerishable ||
        (isSalesOrderPerishable  && !this.excludePerishable())))
    {
        try
        {
            this.cancelShipment(salesTable.SalesId);
        }
        catch (Exception::Error)
        {
            //SO should stay canceled even though TMS engine cancellation failed
            error("@MET:TMSEngineSOCancellationError");
        }
    }
}
